class Solution:
    def maximumGood(self, statements: List[List[int]]) -> int:
        n = len(statements)
        ans = 0
        for mask in range(1 << n):
            ok = True
            for i in range(n):
                if not mask >> i & 1:
                    continue
                for j in range(n):
                    s = statements[i][j]
                    if s == 2:
                        continue
                    if (s == 1 and not mask >> j & 1) or (s == 0 and mask >> j & 1):
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                ans = max(ans, bin(mask).count('1'))
        return ans

