class Solution:
    def maximumGood(self, statements: List[List[int]]) -> int:
        n = len(statements)
        good = [False] * n
        ans = 0
        def compatible(pos, assume):
            for k in range(pos):
                if good[k]:
                    s = statements[k][pos]
                    if (s == 1 and not assume) or (s == 0 and assume):
                        return False
            if assume:
                for j in range(pos):
                    s = statements[pos][j]
                    if s != 2 and (s == 1) != good[j]:
                        return False
            return True
        def dfs(pos, cnt):
            nonlocal ans
            if pos == n:
                ans = max(ans, cnt)
                return
            if compatible(pos, False):
                dfs(pos + 1, cnt)
            good[pos] = True
            if compatible(pos, True):
                dfs(pos + 1, cnt + 1)
            good[pos] = False
        dfs(0, 0)
        return ans

